 19→func newCleanCmd() *cobra.Command {
 20→	var forceFlag bool
 21→
 22→	cmd := &cobra.Command{
 23→		Use:   "clean",
 24→		Short: "Clean up orphaned Entire data",
 25→		Long: `Remove orphaned Entire data (session state, shadow branches, checkpoint metadata, temp files) that wasn't cleaned up automatically.
 26→
 27→This command finds and removes orphaned data from any strategy:
 28→
 29→  Shadow branches (entire/<commit-hash>)
 30→    Normally auto-cleaned when sessions
 31→    are condensed during commits.
 32→
 33→  Session state files (.git/entire-sessions/)
 34→    Track active sessions. Orphaned when no checkpoints or shadow branches
 35→    reference them.
 36→
 37→  Checkpoint metadata (entire/checkpoints/v1 branch)
 38→    Checkpoints are permanent (condensed session history) and are
 39→    never considered orphaned.
 40→
 41→  Temporary files (.entire/tmp/)
 42→    Cached transcripts and other temporary data. Safe to delete when no
 43→    active sessions are using them.
 44→
 45→Default: shows a preview and asks for confirmation before deleting.
 46→With --force, deletes without prompting.
 47→
 48→The entire/checkpoints/v1 branch itself is never deleted.`,
 49→		RunE: func(cmd *cobra.Command, _ []string) error {
 50→			return runClean(cmd.Context(), cmd, forceFlag)
 51→		},
 52→	}
 53→
 54→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Delete without prompting for confirmation")
 55→
 56→	return cmd
 57→}
