 59→func runClean(ctx context.Context, cmd *cobra.Command, force bool) error {
 60→	w := cmd.OutOrStdout()
 61→	errW := cmd.ErrOrStderr()
 62→
 63→	// Initialize logging so structured logs go to .entire/logs/ instead of stderr.
 64→	// Error is non-fatal: if logging init fails, logs go to stderr (acceptable fallback).
 65→	logging.SetLogLevelGetter(GetLogLevel)
 66→	if err := logging.Init(ctx, ""); err == nil {
 67→		defer logging.Close()
 68→	}
 69→
 70→	// List all cleanup items
 71→	items, err := strategy.ListAllCleanupItems(ctx)
 72→	if err != nil {
 73→		return fmt.Errorf("failed to list orphaned items: %w", err)
 74→	}
 75→
 76→	// List temp files
 77→	tempFiles, err := listTempFiles(ctx)
 78→	if err != nil {
 79→		// Non-fatal: continue with other cleanup items
 80→		fmt.Fprintf(errW, "Warning: failed to list temp files: %v\n", err)
 81→	}
 82→
 83→	// Force mode: skip preview and confirmation
 84→	if force {
 85→		return runCleanWithItems(ctx, w, true, items, tempFiles)
 86→	}
 87→
 88→	// Show preview
 89→	if err := runCleanWithItems(ctx, w, false, items, tempFiles); err != nil {
 90→		return err
 91→	}
 92→
 93→	// If nothing to clean, we're done (preview already printed the message)
 94→	totalItems := len(items) + len(tempFiles)
 95→	if totalItems == 0 {
 96→		return nil
 97→	}
 98→
 99→	// Interactive confirmation
100→	var confirmed bool
101→	form := NewAccessibleForm(
102→		huh.NewGroup(
103→			huh.NewConfirm().
104→				Title("Delete these items?").
105→				Affirmative("Yes, delete").
106→				Negative("Cancel").
107→				Value(&confirmed),
108→		),
109→	)
110→
111→	if err := form.Run(); err != nil {
112→		if errors.Is(err, huh.ErrUserAborted) {
113→			return nil
114→		}
115→		return fmt.Errorf("confirmation failed: %w", err)
116→	}
117→
118→	if !confirmed {
119→		fmt.Fprintln(w, "Clean cancelled.")
120→		return nil
121→	}
122→
123→	return runCleanWithItems(ctx, w, true, items, tempFiles)
124→}
