126→// listTempFiles returns files in .entire/tmp/ that are safe to delete,
127→// excluding files belonging to active sessions.
128→func listTempFiles(ctx context.Context) ([]string, error) {
129→	tmpDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
130→	if err != nil {
131→		return nil, fmt.Errorf("failed to get temp dir path: %w", err)
132→	}
133→
134→	entries, err := os.ReadDir(tmpDir)
135→	if os.IsNotExist(err) {
136→		return nil, nil
137→	}
138→	if err != nil {
139→		return nil, fmt.Errorf("failed to read temp dir: %w", err)
140→	}
141→
142→	// Build set of active session IDs to protect their temp files
143→	activeSessionIDs := make(map[string]bool)
144→	if states, listErr := strategy.ListSessionStates(ctx); listErr == nil {
145→		for _, state := range states {
146→			activeSessionIDs[state.SessionID] = true
147→		}
148→	}
149→
150→	var files []string
151→	for _, entry := range entries {
152→		if entry.IsDir() {
153→			continue
154→		}
155→		// Skip temp files belonging to active sessions (e.g., "session-id.json")
156→		name := entry.Name()
157→		sessionID := strings.TrimSuffix(name, ".json")
158→		if sessionID != name && activeSessionIDs[sessionID] {
159→			continue
160→		}
161→		files = append(files, name)
162→	}
163→	return files, nil
164→}
