166→// TempFileDeleteError contains a file name and the error that occurred during deletion.
167→type TempFileDeleteError struct {
168→	File string
169→	Err  error
170→}
171→
172→// deleteTempFiles removes all files in .entire/tmp/.
173→// Returns successfully deleted files and any failures with their error reasons.
174→func deleteTempFiles(ctx context.Context, files []string) (deleted []string, failed []TempFileDeleteError) {
175→	tmpDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
176→	if err != nil {
177→		// Can't get path - mark all as failed with the same error
178→		for _, file := range files {
179→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
180→		}
181→		return nil, failed
182→	}
183→
184→	for _, file := range files {
185→		path := filepath.Join(tmpDir, file)
186→		if err := os.Remove(path); err != nil {
187→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
188→		} else {
189→			deleted = append(deleted, file)
190→		}
191→	}
192→	return deleted, failed
193→}
