315→			for _, state := range result.FailedStates {
316→				fmt.Fprintf(w, "  %s\n", state)
317→			}
318→		}
319→
320→		if len(result.FailedCheckpoints) > 0 {
321→			fmt.Fprintf(w, "\nCheckpoints:\n")
322→			for _, cp := range result.FailedCheckpoints {
323→				fmt.Fprintf(w, "  %s\n", cp)
324→			}
325→		}
326→
327→		if len(failedTempFiles) > 0 {
328→			fmt.Fprintf(w, "\nTemp files:\n")
329→			for _, fe := range failedTempFiles {
330→				fmt.Fprintf(w, "  %s: %v\n", fe.File, fe.Err)
331→			}
