111→// runResetSession handles the --session flag: reset a single session.
112→func runResetSession(ctx context.Context, cmd *cobra.Command, strat *strategy.ManualCommitStrategy, sessionID string, force bool) error {
113→	// Verify the session exists
114→	state, err := strategy.LoadSessionState(ctx, sessionID)
115→	if err != nil {
116→		return fmt.Errorf("failed to load session: %w", err)
117→	}
118→	if state == nil {
119→		return fmt.Errorf("session not found: %s", sessionID)
120→	}
121→
122→	if !force {
123→		var confirmed bool
124→
125→		title := fmt.Sprintf("Reset session %s?", sessionID)
126→		description := fmt.Sprintf("Phase: %s, Checkpoints: %d", state.Phase, state.StepCount)
127→
128→		form := NewAccessibleForm(
129→			huh.NewGroup(
130→				huh.NewConfirm().
131→					Title(title).
132→					Description(description).
133→					Value(&confirmed),
134→			),
135→		)
136→
137→		if err := form.Run(); err != nil {
138→			if errors.Is(err, huh.ErrUserAborted) {
139→				return nil
140→			}
141→			return fmt.Errorf("failed to get confirmation: %w", err)
142→		}
143→
144→		if !confirmed {
145→			return nil
146→		}
147→	}
148→
149→	if err := strat.ResetSession(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionID); err != nil {
150→		return fmt.Errorf("reset session failed: %w", err)
