157→// activeSessionsOnCurrentHead returns sessions on the current HEAD
158→// that are in an active phase (ACTIVE).
159→func activeSessionsOnCurrentHead(ctx context.Context) ([]*session.State, error) {
160→	repo, err := openRepository(ctx)
161→	if err != nil {
162→		return nil, err
163→	}
164→
165→	head, err := repo.Head()
166→	if err != nil {
167→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
168→	}
169→	currentHead := head.Hash().String()
170→
171→	states, err := strategy.ListSessionStates(ctx)
172→	if err != nil {
173→		return nil, fmt.Errorf("failed to list session states: %w", err)
174→	}
175→
176→	var active []*session.State
177→	for _, state := range states {
178→		if state.BaseCommit != currentHead {
179→			continue
180→		}
181→		if state.Phase.IsActive() {
182→			active = append(active, state)
183→		}
184→	}
185→
186→	return active, nil
187→}
