 28→func setupCleanTestRepo(t *testing.T) (*git.Repository, plumbing.Hash) {
 29→	t.Helper()
 30→
 31→	dir := t.TempDir()
 32→	repo, err := git.PlainInit(dir, false)
 33→	if err != nil {
 34→		t.Fatalf("failed to init git repo: %v", err)
 35→	}
 36→
 37→	t.Chdir(dir)
 38→	paths.ClearWorktreeRootCache()
 39→
 40→	// Create initial commit
 41→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
 42→	obj := repo.Storer.NewEncodedObject()
 43→	if err := emptyTree.Encode(obj); err != nil {
 44→		t.Fatalf("failed to encode empty tree: %v", err)
 45→	}
 46→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
 47→	if err != nil {
 48→		t.Fatalf("failed to store empty tree: %v", err)
 49→	}
 50→
 51→	sig := object.Signature{Name: "test", Email: "test@test.com"}
 52→	commit := &object.Commit{
 53→		TreeHash:  emptyTreeHash,
 54→		Author:    sig,
 55→		Committer: sig,
 56→		Message:   "initial commit",
 57→	}
 58→	commitObj := repo.Storer.NewEncodedObject()
 59→	if err := commit.Encode(commitObj); err != nil {
 60→		t.Fatalf("failed to encode commit: %v", err)
 61→	}
 62→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
 63→	if err != nil {
 64→		t.Fatalf("failed to store commit: %v", err)
 65→	}
 66→
 67→	// Create HEAD and master references
 68→	headRef := plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.NewBranchReferenceName("master"))
 69→	if err := repo.Storer.SetReference(headRef); err != nil {
 70→		t.Fatalf("failed to set HEAD: %v", err)
 71→	}
 72→	masterRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("master"), commitHash)
 73→	if err := repo.Storer.SetReference(masterRef); err != nil {
 74→		t.Fatalf("failed to set master: %v", err)
 75→	}
 76→
 77→	return repo, commitHash
 78→}
