282→func TestRunCleanWithItems_PartialFailure(t *testing.T) {
283→	// This test verifies that runCleanWithItems returns an error when some
284→	// deletions fail. We use runCleanWithItems to inject a list
285→	// containing both existing and non-existing items.
286→
287→	repo, commitHash := setupCleanTestRepo(t)
288→
289→	// Create one shadow branch
