295→	// Call runCleanWithItems with a mix of existing and non-existing branches
296→	items := []strategy.CleanupItem{
297→		{Type: strategy.CleanupTypeShadowBranch, ID: "entire/abc1234", Reason: "test"},
298→		{Type: strategy.CleanupTypeShadowBranch, ID: "entire/nonexistent1234567", Reason: "test"},
