304→	// Should return an error because one branch failed to delete
305→	if err == nil {
306→		t.Fatal("runCleanWithItems() should return error when items fail to delete")
307→	}
308→
309→	// Error message should indicate the failure with correct grammar
310→	if !strings.Contains(err.Error(), "failed to delete 1 item") {
311→		t.Errorf("Error should mention 'failed to delete 1 item', got: %v", err)
312→	}
313→	// Verify singular (not "1 items")
