315→		t.Errorf("Error should use singular 'item' for count 1, got: %v", err)
316→	}
317→
318→	// Output should show the successful deletion with ✓ and singular grammar
319→	output := stdout.String()
320→	if !strings.Contains(output, "✓ Deleted 1 item:") {
321→		t.Errorf("Output should show '✓ Deleted 1 item:', got: %s", output)
322→	}
323→
324→	// Output should also show the failure with singular grammar
325→	if !strings.Contains(output, "Failed to delete 1 item:") {
326→		t.Errorf("Output should show 'Failed to delete 1 item:', got: %s", output)
