129→// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
130→// condensed session logs on the entire/checkpoints/v1 branch. These are commits that
131→// were created with session data but the shadow branch has been condensed.
132→//
133→// The function works by:
134→// 1. Getting all checkpoints from the entire/checkpoints/v1 branch
135→// 2. Building a map of checkpoint ID -> checkpoint info
136→// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
137→// 4. Matching by checkpoint ID (stable across amend/rebase)
138→func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
139→	repo, err := OpenRepository(ctx)
140→	if err != nil {
141→		return nil, err
142→	}
143→
144→	// Get all checkpoints from entire/checkpoints/v1 branch
145→	checkpoints, err := s.listCheckpoints(ctx)
146→	if err != nil {
147→		// No checkpoints yet is fine
148→		return nil, nil //nolint:nilerr // Expected when no checkpoints exist
149→	}
150→
151→	if len(checkpoints) == 0 {
152→		return nil, nil
153→	}
154→
155→	// Build map of checkpoint ID -> checkpoint info
156→	// Checkpoint ID is the stable link from Entire-Checkpoint trailer
157→	checkpointInfoMap := make(map[id.CheckpointID]CheckpointInfo)
158→	for _, cp := range checkpoints {
159→		if !cp.CheckpointID.IsEmpty() {
160→			checkpointInfoMap[cp.CheckpointID] = cp
161→		}
162→	}
163→
164→	// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
165→	metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts
166→
167→	head, err := repo.Head()
168→	if err != nil {
169→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
170→	}
171→
172→	// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
173→	iter, err := repo.Log(&git.LogOptions{
174→		From:  head.Hash(),
175→		Order: git.LogOrderCommitterTime,
176→	})
177→	if err != nil {
178→		return nil, fmt.Errorf("failed to get commit log: %w", err)
179→	}
180→
181→	var points []RewindPoint
182→	count := 0
183→
184→	err = iter.ForEach(func(c *object.Commit) error {
185→		if err := ctx.Err(); err != nil {
186→			return err //nolint:wrapcheck // Propagating context cancellation
187→		}
188→		if count >= logsOnlyScanLimit {
189→			return errStop
190→		}
191→		count++
192→
193→		// Extract all checkpoint IDs from Entire-Checkpoint trailers.
194→		// Squash merge commits may contain multiple trailers from the original commits.
195→		allCpIDs := trailers.ParseAllCheckpoints(c.Message)
196→		if len(allCpIDs) == 0 {
197→			return nil
198→		}
199→
200→		// Resolve to the latest checkpoint by creation time (consistent with `entire resume`).
201→		cpInfo, found := ResolveLatestCheckpointFromMap(allCpIDs, checkpointInfoMap)
202→		if !found {
203→			return nil
204→		}
205→
206→		// Create logs-only rewind point
207→		message := strings.Split(c.Message, "\n")[0]
208→
209→		// Read session prompts from metadata tree
210→		var sessionPrompt string
211→		var sessionPrompts []string
212→		if metadataTree != nil {
213→			checkpointPath := paths.CheckpointPath(cpInfo.CheckpointID) //nolint:staticcheck // already present in codebase
214→			// For multi-session checkpoints, read all prompts
215→			if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
216→				sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
217→				// Use the last (most recent) prompt as the main session prompt
218→				if len(sessionPrompts) > 0 {
219→					sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
220→				}
221→			} else {
222→				sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
223→				if sessionPrompt != "" {
224→					sessionPrompts = []string{sessionPrompt}
225→				}
226→			}
227→		}
228→
229→		points = append(points, RewindPoint{
230→			ID:             c.Hash.String(),
231→			Message:        message,
232→			Date:           c.Author.When,
233→			IsLogsOnly:     true,
234→			CheckpointID:   cpInfo.CheckpointID,
235→			Agent:          cpInfo.Agent,
236→			SessionID:      cpInfo.SessionID,
237→			SessionPrompt:  sessionPrompt,
238→			SessionCount:   cpInfo.SessionCount,
239→			SessionIDs:     cpInfo.SessionIDs,
240→			SessionPrompts: sessionPrompts,
241→		})
242→
243→		return nil
244→	})
245→
246→	if err != nil && !errors.Is(err, errStop) {
247→		return nil, fmt.Errorf("error iterating commits: %w", err)
248→	}
249→
250→	if len(points) > limit {
251→		points = points[:limit]
252→	}
253→
254→	return points, nil
255→}
