276→// Rewind restores the working directory to a checkpoint.
277→//
278→
279→func (s *ManualCommitStrategy) Rewind(ctx context.Context, w, errW io.Writer, point RewindPoint) error {
280→	repo, err := OpenRepository(ctx)
281→	if err != nil {
282→		return fmt.Errorf("failed to open git repository: %w", err)
283→	}
284→
285→	// Get the checkpoint commit
286→	commitHash := plumbing.NewHash(point.ID)
287→	commit, err := repo.CommitObject(commitHash)
288→	if err != nil {
289→		return fmt.Errorf("failed to get commit: %w", err)
290→	}
291→
292→	tree, err := commit.Tree()
293→	if err != nil {
294→		return fmt.Errorf("failed to get tree: %w", err)
295→	}
296→
297→	// Reset the shadow branch to the rewound checkpoint
298→	// This ensures the next checkpoint will only include prompts from this point forward
299→	if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
300→		// Log warning but don't fail - file restoration is the primary operation
301→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
302→	}
303→
304→	// Load session state to get untracked files that existed at session start
305→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
306→	var preservedUntrackedFiles map[string]bool
307→	if hasSessionTrailer {
308→		state, stateErr := s.loadSessionState(ctx, sessionID)
309→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
310→			preservedUntrackedFiles = make(map[string]bool)
311→			for _, f := range state.UntrackedFilesAtStart {
312→				preservedUntrackedFiles[f] = true
313→			}
314→		}
315→	}
316→
317→	// Build set of files in the checkpoint tree (excluding metadata)
318→	checkpointFiles := make(map[string]bool)
319→	err = tree.Files().ForEach(func(f *object.File) error {
320→		if err := ctx.Err(); err != nil {
321→			return err //nolint:wrapcheck // Propagating context cancellation
322→		}
323→		if !strings.HasPrefix(f.Name, entireDir) {
324→			checkpointFiles[f.Name] = true
325→		}
326→		return nil
327→	})
328→	if err != nil {
329→		return fmt.Errorf("failed to list checkpoint files: %w", err)
330→	}
331→
332→	// Get HEAD tree to identify tracked files
333→	head, err := repo.Head()
334→	if err != nil {
335→		return fmt.Errorf("failed to get HEAD: %w", err)
336→	}
337→	headCommit, err := repo.CommitObject(head.Hash())
338→	if err != nil {
339→		return fmt.Errorf("failed to get HEAD commit: %w", err)
340→	}
341→	headTree, err := headCommit.Tree()
342→	if err != nil {
343→		return fmt.Errorf("failed to get HEAD tree: %w", err)
344→	}
345→
346→	// Build set of files tracked in HEAD
347→	trackedFiles := make(map[string]bool)
348→	//nolint:errcheck // Error is not critical for rewind
349→	_ = headTree.Files().ForEach(func(f *object.File) error {
350→		if err := ctx.Err(); err != nil {
351→			return err //nolint:wrapcheck // Propagating context cancellation
352→		}
353→		trackedFiles[f.Name] = true
354→		return nil
355→	})
356→
357→	// Get repository root to walk from there
358→	repoRoot, err := paths.WorktreeRoot(ctx)
359→	if err != nil {
360→		repoRoot = "." // Fallback to current directory
361→	}
362→
363→	// Open os.Root at repo root for traversal-resistant file operations.
364→	// Defense-in-depth: paths come from git tree objects (trusted) but we
365→	// still scope operations to prevent any escape from the repo root.
366→	repoRootHandle, err := os.OpenRoot(repoRoot)
367→	if err != nil {
368→		return fmt.Errorf("failed to open repo root: %w", err)
369→	}
370→	defer repoRootHandle.Close()
371→
372→	// Find and delete untracked files that aren't in the checkpoint.
373→	// Uses git ls-files to only consider non-ignored files, avoiding walks through
374→	// large ignored directories like node_modules/.
375→	untrackedNow, err := collectUntrackedFiles(ctx)
376→	if err != nil {
377→		// Non-fatal - continue with restoration
378→		fmt.Fprintf(errW, "Warning: error listing untracked files: %v\n", err)
379→	}
380→	for _, relPath := range untrackedNow {
381→		// If file is in checkpoint, it will be restored
382→		if checkpointFiles[relPath] {
383→			continue
384→		}
385→
386→		// If file is tracked in HEAD, don't delete (user's committed work)
387→		if trackedFiles[relPath] {
388→			continue
389→		}
390→
391→		// If file existed at session start, preserve it (untracked user files)
392→		if preservedUntrackedFiles[relPath] {
393→			continue
394→		}
395→
396→		// File is untracked and not in checkpoint - delete it via os.Root
397→		if removeErr := osroot.Remove(repoRootHandle, relPath); removeErr == nil {
398→			fmt.Fprintf(w, "  Deleted: %s\n", relPath)
399→		}
400→	}
401→
402→	// Restore files from checkpoint
403→	err = tree.Files().ForEach(func(f *object.File) error {
404→		if err := ctx.Err(); err != nil {
405→			return err //nolint:wrapcheck // Propagating context cancellation
406→		}
407→		// Skip metadata directories - these are for checkpoint storage, not working dir
408→		if strings.HasPrefix(f.Name, entireDir) {
409→			return nil
410→		}
411→
412→		contents, err := f.Contents()
413→		if err != nil {
414→			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
415→		}
416→
417→		// Ensure directory exists (MkdirAll not available on os.Root)
418→		absPath := filepath.Join(repoRoot, f.Name)
419→		dir := filepath.Dir(absPath)
420→		if dir != "." {
421→			//nolint:gosec // G301: Need 0o755 for user directories during rewind
422→			if err := os.MkdirAll(dir, 0o755); err != nil {
423→				return fmt.Errorf("failed to create directory %s: %w", dir, err)
424→			}
425→		}
426→
427→		// Write file with appropriate permissions via os.Root
428→		var perm os.FileMode = 0o644
429→		if f.Mode == filemode.Executable {
430→			perm = 0o755
431→		}
432→		if err := osroot.WriteFile(repoRootHandle, f.Name, []byte(contents), perm); err != nil {
433→			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
434→		}
435→
436→		fmt.Fprintf(w, "  Restored: %s\n", f.Name)
437→		return nil
438→	})
439→	if err != nil {
440→		return fmt.Errorf("failed to iterate tree files: %w", err)
441→	}
442→
443→	fmt.Fprintln(w)
444→	if len(point.ID) >= 7 {
445→		fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID[:7])
446→	} else {
447→		fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID)
448→	}
449→	fmt.Fprintln(w)
450→
451→	return nil
452→}
453→
454→// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
455→// This ensures that when the user commits after rewinding, the next checkpoint will only
456→// include prompts from the rewound point, not prompts from later checkpoints.
457→func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
458→	// Extract session ID from the checkpoint commit's Entire-Session trailer
459→	sessionID, found := trailers.ParseSession(commit.Message)
460→	if !found {
461→		return errors.New("checkpoint has no Entire-Session trailer")
462→	}
463→
464→	// Load session state to get the shadow branch name
465→	state, err := s.loadSessionState(ctx, sessionID)
466→	if err != nil {
467→		return fmt.Errorf("failed to load session state: %w", err)
468→	}
469→	if state == nil {
470→		return fmt.Errorf("session %s not found", sessionID)
471→	}
472→
473→	// Reset the shadow branch to the checkpoint commit
474→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
475→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
476→
477→	// Update the reference to point to the checkpoint commit
478→	ref := plumbing.NewHashReference(refName, commit.Hash)
479→	if err := repo.Storer.SetReference(ref); err != nil {
480→		return fmt.Errorf("failed to update shadow branch: %w", err)
481→	}
482→
483→	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
484→	return nil
485→}
486→
487→// CanRewind checks if rewinding is possible.
488→// For manual-commit strategy, rewind restores files from a checkpoint - uncommitted changes are expected
489→// and will be replaced by the checkpoint contents. Returns true with a warning message showing
490→// what changes will be reverted.
491→func (s *ManualCommitStrategy) CanRewind(ctx context.Context) (bool, string, error) {
492→	return checkCanRewindWithWarning(ctx)
493→}
494→
495→// PreviewRewind returns what will happen if rewinding to the given point.
496→// This allows showing warnings about untracked files that will be deleted.
497→func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
498→	// Logs-only points don't modify the working directory
499→	if point.IsLogsOnly {
500→		return &RewindPreview{}, nil
501→	}
502→
503→	repo, err := OpenRepository(ctx)
504→	if err != nil {
505→		return nil, fmt.Errorf("failed to open git repository: %w", err)
506→	}
507→
508→	// Get the checkpoint commit
509→	commitHash := plumbing.NewHash(point.ID)
510→	commit, err := repo.CommitObject(commitHash)
511→	if err != nil {
512→		return nil, fmt.Errorf("failed to get commit: %w", err)
513→	}
514→
515→	tree, err := commit.Tree()
516→	if err != nil {
517→		return nil, fmt.Errorf("failed to get tree: %w", err)
518→	}
519→
520→	// Load session state to get untracked files that existed at session start
521→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
522→	var preservedUntrackedFiles map[string]bool
523→	if hasSessionTrailer {
524→		state, stateErr := s.loadSessionState(ctx, sessionID)
525→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
526→			preservedUntrackedFiles = make(map[string]bool)
527→			for _, f := range state.UntrackedFilesAtStart {
528→				preservedUntrackedFiles[f] = true
529→			}
530→		}
531→	}
532→
533→	// Build set of files in the checkpoint tree (excluding metadata)
534→	checkpointFiles := make(map[string]bool)
535→	var filesToRestore []string
536→	err = tree.Files().ForEach(func(f *object.File) error {
537→		if err := ctx.Err(); err != nil {
538→			return err //nolint:wrapcheck // Propagating context cancellation
539→		}
540→		if !strings.HasPrefix(f.Name, entireDir) {
541→			checkpointFiles[f.Name] = true
542→			filesToRestore = append(filesToRestore, f.Name)
543→		}
544→		return nil
545→	})
546→	if err != nil {
547→		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
548→	}
549→
550→	// Get HEAD tree to identify tracked files
551→	head, err := repo.Head()
552→	if err != nil {
553→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
554→	}
555→	headCommit, err := repo.CommitObject(head.Hash())
556→	if err != nil {
557→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
558→	}
559→	headTree, err := headCommit.Tree()
560→	if err != nil {
561→		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
562→	}
563→
564→	// Build set of files tracked in HEAD
565→	trackedFiles := make(map[string]bool)
566→	//nolint:errcheck // Error is not critical for preview
567→	_ = headTree.Files().ForEach(func(f *object.File) error {
568→		if err := ctx.Err(); err != nil {
569→			return err //nolint:wrapcheck // Propagating context cancellation
570→		}
571→		trackedFiles[f.Name] = true
572→		return nil
573→	})
574→
575→	// Find untracked files that would be deleted.
576→	// Uses git ls-files to only consider non-ignored files.
577→	var filesToDelete []string
578→	untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
579→	if untrackedErr != nil {
580→		fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
581→		return &RewindPreview{
582→			FilesToRestore: filesToRestore,
583→			FilesToDelete:  filesToDelete,
584→		}, nil
585→	}
586→	for _, relPath := range untrackedNow {
587→		if checkpointFiles[relPath] {
588→			continue
589→		}
590→		if trackedFiles[relPath] {
591→			continue
592→		}
593→		if preservedUntrackedFiles[relPath] {
594→			continue
595→		}
596→		filesToDelete = append(filesToDelete, relPath)
597→	}
598→
599→	// Sort for consistent output
600→	sort.Strings(filesToRestore)
601→	sort.Strings(filesToDelete)
602→
603→	return &RewindPreview{
604→		FilesToRestore: filesToRestore,
605→		FilesToDelete:  filesToDelete,
606→	}, nil
607→}
608→
609→// RestoreLogsOnly restores session logs from a logs-only rewind point.
610→// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
611→// Does not modify the working directory.
612→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
613→// If force is false, prompts for confirmation when local logs have newer timestamps.
614→// Returns info about each restored session so callers can print correct per-session resume commands.
615→func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, w, errW io.Writer, point RewindPoint, force bool) ([]RestoredSession, error) {
616→	if !point.IsLogsOnly {
617→		return nil, errors.New("not a logs-only rewind point")
618→	}
619→
620→	if point.CheckpointID.IsEmpty() {
621→		return nil, errors.New("missing checkpoint ID")
622→	}
623→
624→	// Get checkpoint store
625→	store, err := s.getCheckpointStore()
626→	if err != nil {
627→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
628→	}
629→
630→	// Read checkpoint summary to get session count
631→	summary, err := store.ReadCommitted(ctx, point.CheckpointID)
632→	if err != nil {
633→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
634→	}
635→	if summary == nil {
636→		return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
637→	}
638→
639→	// Get worktree root for agent session directory lookup
640→	repoRoot, err := paths.WorktreeRoot(ctx)
641→	if err != nil {
642→		return nil, fmt.Errorf("failed to get worktree root: %w", err)
643→	}
644→
645→	// Check for newer local logs if not forcing
646→	if !force {
647→		sessions := s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary)
648→		hasConflicts := false
649→		for _, sess := range sessions {
650→			if sess.Status == StatusLocalNewer {
651→				hasConflicts = true
652→				break
653→			}
654→		}
655→		if hasConflicts {
656→			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(errW, sessions)
657→			if promptErr != nil {
658→				return nil, promptErr
659→			}
660→			if !shouldOverwrite {
661→				fmt.Fprintf(w, "Resume cancelled. Local session logs preserved.\n")
662→				return nil, nil
663→			}
664→		}
665→	}
666→
667→	// Count sessions to restore
668→	totalSessions := len(summary.Sessions)
669→	if totalSessions > 1 {
670→		fmt.Fprintf(w, "Restoring %d sessions from checkpoint:\n", totalSessions)
671→	}
672→
673→	// Restore all sessions (oldest to newest, using 0-based indexing)
674→	var restored []RestoredSession
675→	for i := range totalSessions {
676→		content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
677→		if readErr != nil {
678→			fmt.Fprintf(errW, "  Warning: failed to read session %d: %v\n", i, readErr)
679→			continue
680→		}
681→		if content == nil || len(content.Transcript) == 0 {
682→			continue
683→		}
684→
685→		sessionID := content.Metadata.SessionID
686→		if sessionID == "" {
687→			fmt.Fprintf(errW, "  Warning: session %d has no session ID, skipping\n", i)
688→			continue
689→		}
690→
691→		// Resolve per-session agent from metadata — skip if agent is unknown
692→		if content.Metadata.Agent == "" {
693→			fmt.Fprintf(errW, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
694→			continue
695→		}
696→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
697→		if agErr != nil {
698→			fmt.Fprintf(errW, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
699→			continue
700→		}
701→
702→		// Compute transcript path from current repo location for cross-machine portability.
703→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
704→		if dirErr != nil {
705→			fmt.Fprintf(errW, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
706→			continue
707→		}
708→		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
709→
710→		// Get first prompt for display
711→		promptPreview := ExtractFirstPrompt(content.Prompts)
712→
713→		if totalSessions > 1 {
714→			isLatest := i == totalSessions-1
715→			if promptPreview != "" {
716→				if isLatest {
717→					fmt.Fprintf(w, "  Session %d (latest): %s\n", i+1, promptPreview)
718→				} else {
719→					fmt.Fprintf(w, "  Session %d: %s\n", i+1, promptPreview)
720→				}
721→			}
722→			fmt.Fprintf(w, "    Writing to: %s\n", sessionFile)
723→		} else {
724→			fmt.Fprintf(w, "Writing transcript to: %s\n", sessionFile)
725→		}
726→
727→		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
728→		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
729→			fmt.Fprintf(errW, "    Warning: failed to create directory: %v\n", mkdirErr)
730→			continue
731→		}
732→
733→		agentSession := &agent.AgentSession{
734→			SessionID:  sessionID,
735→			AgentName:  sessionAgent.Name(),
736→			RepoPath:   repoRoot,
737→			SessionRef: sessionFile,
738→			NativeData: content.Transcript,
739→		}
740→		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
741→			if totalSessions > 1 {
742→				fmt.Fprintf(errW, "    Warning: failed to write session: %v\n", writeErr)
743→				continue
744→			}
745→			return nil, fmt.Errorf("failed to write session: %w", writeErr)
746→		}
747→
748→		restored = append(restored, RestoredSession{
749→			SessionID: sessionID,
750→			Agent:     sessionAgent.Type(),
751→			Prompt:    promptPreview,
752→			CreatedAt: content.Metadata.CreatedAt,
753→		})
754→	}
755→
756→	return restored, nil
757→}
758→
759→// ResolveAgentForRewind resolves the agent from checkpoint metadata.
760→func ResolveAgentForRewind(agentType types.AgentType) (agent.Agent, error) {
761→	ag, err := agent.GetByAgentType(agentType)
762→	if err != nil {
763→		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
764→	}
765→	return ag, nil
766→}
767→
768→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
769→// Returns an empty string if the prompt cannot be read.
770→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
771→	// Get the commit and its tree
772→	commit, err := repo.CommitObject(commitHash)
773→	if err != nil {
774→		return ""
775→	}
776→
777→	tree, err := commit.Tree()
778→	if err != nil {
779→		return ""
780→	}
781→
782→	// Look for prompt.txt in the metadata directory
783→	promptPath := metadataDir + "/" + paths.PromptFileName
784→	promptEntry, err := tree.File(promptPath)
785→	if err != nil {
786→		return ""
787→	}
788→
789→	content, err := promptEntry.Contents()
790→	if err != nil {
791→		return ""
792→	}
793→
794→	return ExtractFirstPrompt(content)
795→}
796→
797→// SessionRestoreStatus represents the status of a session being restored.
798→type SessionRestoreStatus int
799→
800→const (
801→	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
802→	StatusUnchanged                                   // Local and checkpoint are the same
803→	StatusCheckpointNewer                             // Checkpoint has newer entries
804→	StatusLocalNewer                                  // Local has newer entries (conflict)
805→)
806→
807→// SessionRestoreInfo contains information about a session being restored.
808→type SessionRestoreInfo struct {
809→	SessionID      string
810→	Prompt         string               // First prompt preview for display
811→	Status         SessionRestoreStatus // Status of this session
812→	LocalTime      time.Time
813→	CheckpointTime time.Time
814→}
815→
816→// classifySessionsForRestore checks all sessions in a checkpoint and returns info
817→// about each session, including whether local logs have newer timestamps.
818→// repoRoot is used to compute per-session agent directories.
819→// Sessions without agent metadata are skipped (cannot determine target directory).
820→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
821→	var sessions []SessionRestoreInfo
822→
823→	totalSessions := len(summary.Sessions)
824→	// Check all sessions (0-based indexing)
825→	for i := range totalSessions {
826→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
827→		if err != nil || content == nil || len(content.Transcript) == 0 {
828→			continue
829→		}
830→
831→		sessionID := content.Metadata.SessionID
832→		if sessionID == "" || content.Metadata.Agent == "" {
833→			continue
834→		}
835→
836→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
837→		if agErr != nil {
838→			continue
839→		}
840→
841→		// Compute transcript path from current repo location for cross-machine portability.
842→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
843→		if dirErr != nil {
844→			continue
845→		}
846→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
847→
848→		localTime := paths.GetLastTimestampFromFile(localPath)
849→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
850→		status := ClassifyTimestamps(localTime, checkpointTime)
851→
852→		sessions = append(sessions, SessionRestoreInfo{
853→			SessionID:      sessionID,
854→			Prompt:         ExtractFirstPrompt(content.Prompts),
855→			Status:         status,
856→			LocalTime:      localTime,
857→			CheckpointTime: checkpointTime,
858→		})
859→	}
860→
861→	return sessions
862→}
863→
864→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
865→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
866→	// Local file doesn't exist (no timestamp found)
867→	if localTime.IsZero() {
868→		return StatusNew
869→	}
870→
871→	// Can't determine checkpoint time - treat as new/safe
872→	if checkpointTime.IsZero() {
873→		return StatusNew
874→	}
875→
876→	// Compare timestamps
877→	if localTime.After(checkpointTime) {
878→		return StatusLocalNewer
879→	}
880→	if checkpointTime.After(localTime) {
881→		return StatusCheckpointNewer
882→	}
883→	return StatusUnchanged
884→}
885→
886→// StatusToText returns a human-readable status string.
887→func StatusToText(status SessionRestoreStatus) string {
888→	switch status {
889→	case StatusNew:
890→		return "(new)"
891→	case StatusUnchanged:
892→		return "(unchanged)"
893→	case StatusCheckpointNewer:
894→		return "(checkpoint is newer)"
895→	case StatusLocalNewer:
896→		return "(local is newer)" // shouldn't appear in non-conflict list
897→	default:
898→		return ""
899→	}
900→}
901→
902→// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
903→// session logs that have newer timestamps than the checkpoint versions.
904→func PromptOverwriteNewerLogs(errW io.Writer, sessions []SessionRestoreInfo) (bool, error) {
905→	// Separate conflicting and non-conflicting sessions
906→	var conflicting, nonConflicting []SessionRestoreInfo
907→	for _, s := range sessions {
908→		if s.Status == StatusLocalNewer {
909→			conflicting = append(conflicting, s)
910→		} else {
911→			nonConflicting = append(nonConflicting, s)
912→		}
913→	}
914→
915→	fmt.Fprintf(errW, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
916→	for _, info := range conflicting {
917→		// Show prompt if available, otherwise fall back to session ID
918→		if info.Prompt != "" {
919→			fmt.Fprintf(errW, "  \"%s\"\n", info.Prompt)
920→		} else {
921→			fmt.Fprintf(errW, "  Session: %s\n", info.SessionID)
922→		}
923→		fmt.Fprintf(errW, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
924→		fmt.Fprintf(errW, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
925→	}
926→
927→	// Show non-conflicting sessions with their status
928→	if len(nonConflicting) > 0 {
929→		fmt.Fprintf(errW, "\nThese other session(s) will also be restored:\n")
930→		for _, info := range nonConflicting {
931→			statusText := StatusToText(info.Status)
932→			if info.Prompt != "" {
933→				fmt.Fprintf(errW, "  \"%s\" %s\n", info.Prompt, statusText)
934→			} else {
935→				fmt.Fprintf(errW, "  Session: %s %s\n", info.SessionID, statusText)
936→			}
937→		}
938→	}
939→
940→	fmt.Fprintf(errW, "\nOverwriting will lose the newer local entries.\n\n")
941→
942→	var confirmed bool
943→	form := huh.NewForm(
944→		huh.NewGroup(
945→			huh.NewConfirm().
946→				Title("Overwrite local session logs with checkpoint versions?").
947→				Value(&confirmed),
948→		),
949→	)
950→	if isAccessibleMode() {
951→		form = form.WithAccessible(true)
952→	}
953→
954→	if err := form.Run(); err != nil {
955→		if errors.Is(err, huh.ErrUserAborted) {
956→			return false, nil
957→		}
958→		return false, fmt.Errorf("failed to get confirmation: %w", err)
959→	}
960→
961→	return confirmed, nil
962→}
